#include <string>
#include <cctype> // for std::tolower

int countVowels(const std::string& str) {
    int count = 0;
    for (char ch : str) {
        char lowerCh = std::tolower(static_cast<unsigned char>(ch)); // Prevent overflow
        if (lowerCh == 'a' || lowerCh == 'e' || lowerCh == 'i' || lowerCh == 'o' || lowerCh == 'u') {
            ++count;
        }
    }
    return count;
}
